using System;
using System.Runtime.InteropServices;
sealed class SafeFileHandle : SafeHandleZeroOrMinusOneIsInvalid {
    public SafeFileHandle() : base(ownsHandle: true) {}
    protected override bool ReleaseHandle() => CloseHandle(handle);   // once, guarded
}

void Use(string path) {
    using var h = OpenFile(path);                 // released on every exit path
    var weak = new WeakReference<SafeFileHandle>(h);
    if (weak.TryGetTarget(out var alive)) Consume(alive);
}
